SELECT ENAME, SAL FROM EMP;
SELECT *
Definition: The asterisk means all columns from the selected table.

SELECT ENAME, DEPTNO, SAL, ROW_NUMBER() OVER ( PARTITION BY DEPTNO ORDER BY SAL DESC ) AS rn FROM EMP;
-- Top 3 employees in each department SELECT * FROM ( SELECT ENAME, DEPTNO, SAL, ROW_NUMBER() OVER ( PARTITION BY DEPTNO
ORDER BY SAL DESC ) AS rn FROM EMP ) WHERE rn <= 3;
